// Package brand carries the product's own artwork into the binary.
//
// Embedded rather than shipped beside the executable because the agent is
// installed by copying one file: anything that has to travel separately will
// eventually not travel, and the first sign of that is a blank icon in a list
// somebody is using to decide whether the product installed correctly.
package brand

import _ "embed"

// Icon is the Windows icon, in ICO format with sizes from 16 to 256.
//
// Generated by scripts/icon/make-icon.py from the same drawing as the macOS
// .icns and the web favicon, so the three cannot drift apart.
//
//go:embed wxt-agent.ico
var Icon []byte
